// Normaliza el webhook de wppia (messages.upsert) o el disparo horario de seguimientos.
const cfg = $('Config').first().json;
const item = $input.first().json;
const digits = (v) => String(v ?? '').replace(/\D/g, '');
const last9 = (v) => digits(v).slice(-9);
const lista = (v) => String(v ?? '').split(/[,;\s]+/).map(last9).filter(Boolean);
const skip = (reason) => [{ json: { route: 'skip', reason } }];

// Disparo del Schedule Trigger: no trae body.
if (item.body === undefined) return [{ json: { route: 'scan' } }];

// Sin secreto configurado el webhook quedaría abierto a cualquiera: se descarta todo.
const secret = String(cfg.webhookSecret ?? '').trim();
if (!secret || secret === 'CAMBIAR') return skip('configurar_webhookSecret');
if (String(item.headers?.['x-webhook-secret'] ?? '') !== secret) return skip('secreto_invalido');

const body = item.body ?? {};
if (!['messages.upsert', 'messages.received'].includes(body.event)) return skip('evento_' + body.event);

const raw = Array.isArray(body.data?.messages) ? body.data.messages[0] : body.data?.messages;
if (!raw?.key) return skip('sin_mensaje');

const key = raw.key;
const jid = String(key.remoteJid ?? raw.remoteJid ?? '');
if (jid.endsWith('@g.us') || jid.includes('broadcast') || raw.broadcast === true) return skip('grupo_o_difusion');

const fromMe = key.fromMe === true;
// Con LID el remoteJid no es el teléfono: se usa el número real que informa wppia.
const phone = fromMe
  ? digits(jid.endsWith('@s.whatsapp.net') ? jid : key.senderPn || key.cleanedSenderPn || '')
  : digits(key.cleanedSenderPn || key.senderPn || (jid.endsWith('@s.whatsapp.net') ? jid : ''));
if (!phone) return skip('sin_telefono');

// Números que el bot nunca atiende.
const interno = last9(cfg.notificarA);
if (interno && last9(phone) === interno) return skip('numero_interno');
if (lista(cfg.excluir).includes(last9(phone))) return skip('excluido');
const prueba = lista(cfg.soloPrueba);
if (prueba.length && !prueba.includes(last9(phone))) return skip('fuera_de_la_lista_de_prueba');

// Desenvuelve mensajes efímeros / de una sola vista / documento con caption.
let m = raw.message ?? {};
for (let i = 0; i < 3; i++) {
  m = m.ephemeralMessage?.message ?? m.viewOnceMessage?.message ?? m.viewOnceMessageV2?.message
    ?? m.documentWithCaptionMessage?.message ?? m;
}

let kind;
let text = String(raw.messageBody ?? m.conversation ?? m.extendedTextMessage?.text ?? '').trim();
let seconds = 0;
let fileName = null;
let location = null;

if (m.reactionMessage || m.protocolMessage || m.senderKeyDistributionMessage) return skip('mensaje_de_sistema');
else if (m.audioMessage) { kind = 'audio'; seconds = Number(m.audioMessage.seconds) || 0; }
else if (m.imageMessage) { kind = 'image'; text = text || String(m.imageMessage.caption ?? ''); }
else if (m.videoMessage) { kind = 'video'; text = text || String(m.videoMessage.caption ?? ''); }
else if (m.documentMessage) {
  kind = 'document';
  fileName = m.documentMessage.fileName || m.documentMessage.title || null;
  text = text || String(m.documentMessage.caption ?? '');
}
else if (m.locationMessage) {
  kind = 'location';
  location = { lat: m.locationMessage.degreesLatitude, lng: m.locationMessage.degreesLongitude };
}
else if (m.contactMessage || m.contactsArrayMessage) kind = 'contact';
else if (m.stickerMessage) kind = 'sticker';
else if (text) kind = 'text';
else return skip('vacio');

return [{
  json: {
    route: fromMe ? 'fromMe' : 'inbound',
    phone,
    name: String(raw.pushName ?? '').trim(),
    messageId: String(key.id ?? raw.id ?? ''),
    kind,
    text,
    seconds,
    fileName,
    location,
    tsMs: Number(raw.messageTimestamp) ? Number(raw.messageTimestamp) * 1000 : Date.now(),
    // Lo que pide POST /api/decrypt-media de wppia para bajar el audio.
    rawForMedia: { key: { id: key.id }, message: raw.message },
  },
}];

// Mensaje saliente (fromMe): si no es eco del bot, una persona tomó el chat y el bot se calla.
const cfg = $('Config').first().json;
const msg = $('Normalizar mensaje').first().json;
const row = $input.first().json;
const now = Date.now();

let e = {};
try { e = row.estado ? JSON.parse(row.estado) : {}; } catch { e = {}; }

// wppia reenvía como fromMe lo que el propio bot envía: se ignora durante 90 s.
if (e.lastBotAt && now - e.lastBotAt < 90_000) {
  return [{ json: { guardar: false, motivo: 'eco_del_bot' } }];
}

const horas = Number(cfg.pausaHoras) > 0 ? Number(cfg.pausaHoras) : 8;
e.phone = msg.phone;
e.pausedUntil = now + horas * 3600e3;
e.humano = true;
e.lastHumanAt = now;

return [{ json: { guardar: true, phone: msg.phone, estado: JSON.stringify(e) } }];

// Decide si el bot responde este mensaje y actualiza la ficha del chat.
const cfg = $('Config').first().json;
const msg = $('Normalizar mensaje').first().json;
const row = $input.first().json;
const now = Date.now();

let e = {};
try { e = row.estado ? JSON.parse(row.estado) : {}; } catch { e = {}; }

const duplicado = (e.ids ?? []).includes(msg.messageId);
e.phone = msg.phone;
e.name = e.name || msg.name || '';
e.firstAt = e.firstAt || now;
e.stage = e.stage || 'NUEVO';
e.lastInAt = now;
e.inCount = (e.inCount || 0) + 1;
e.ids = [...(e.ids ?? []), msg.messageId].slice(-30);
e.hist = (e.hist ?? []).filter((t) => now - t < 3600e3);

let responder = true;
let motivo = null;
const trivial = /^(ok|oka|okey|okis|dale|listo|gracias|muchas gracias|jaja|ja|👍|🙏|\.)+[\s!.]*$/i;

if (duplicado) { responder = false; motivo = 'duplicado'; }
else if (cfg.botActivo === false) { responder = false; motivo = 'bot_apagado'; }
else if (e.pausedUntil && e.pausedUntil > now) { responder = false; motivo = 'pausado_por_persona'; }
else if (e.hist.length >= 10) {
  // Corta cualquier bucle o abuso: más de 10 respuestas en una hora.
  responder = false; motivo = 'limite_por_hora'; e.pausedUntil = now + 2 * 3600e3;
}
else if (msg.kind === 'text' && trivial.test(msg.text) && (e.botReplies || 0) > 0) {
  responder = false; motivo = 'mensaje_de_cortesia';
}

return [{ json: { ...msg, e, estado: JSON.stringify(e), responder, motivo } }];

// Unifica el texto del mensaje (texto, audio transcripto, adjunto, ubicación) y arma el buffer anti-ráfaga.
const base = $('Estado del chat').first().json;
const inp = $input.first().json;
const e = base.e;
const cap = base.text ? ' con el texto: "' + base.text + '"' : '';
let text;

switch (base.kind) {
  case 'audio':
    if (inp.audioLargo) text = '[AUDIO MUY LARGO, no se transcribió: pedile amablemente que lo resuma por escrito]';
    else if (typeof inp.text === 'string' && inp.text.trim()) text = '[Audio transcripto] ' + inp.text.trim();
    else text = '[AUDIO NO COMPRENDIDO, falló la transcripción: pedile que lo escriba]';
    break;
  case 'image': text = '[El cliente envió una imagen' + cap + ']'; break;
  case 'video': text = '[El cliente envió un video' + cap + ']'; break;
  case 'document': text = '[El cliente envió un documento' + (base.fileName ? ' llamado "' + base.fileName + '"' : '') + cap + ']'; break;
  case 'location': text = '[El cliente compartió su ubicación GPS]'; break;
  case 'contact': text = '[El cliente compartió un contacto]'; break;
  case 'sticker': text = '[El cliente envió un sticker]'; break;
  default: text = base.text;
}

// Adjuntos y ubicación quedan anotados para el equipo humano.
if (['image', 'document', 'video', 'location', 'contact'].includes(base.kind)) {
  e.adjuntos = [...(e.adjuntos ?? []), { tipo: base.kind, at: Date.now(), archivo: base.fileName ?? null }].slice(-20);
}
if (base.location) e.ubicacion = base.location;

const prev = String($('Leer estado (entrante)').first().json.buffer ?? '').trim();
const buffer = prev ? prev + '\n' + text : text;

return [{
  json: { ...base, text, e, estado: JSON.stringify(e), buffer, lastMsgId: base.messageId },
}];

// Tras la espera: solo sigue la ejecución del ÚLTIMO mensaje de la ráfaga, con todo el texto junto.
const base = $('Texto final').first().json;
const row = $input.first().json;
const now = Date.now();

let e = base.e;
try { if (row.estado) e = JSON.parse(row.estado); } catch { /* usa el estado local */ }

if (String(row.lastMsgId ?? '') !== String(base.messageId)) {
  return [{ json: { continuar: false, motivo: 'llego_otro_mensaje' } }];
}
// Una persona pudo haber tomado el chat mientras esperábamos.
if (e.pausedUntil && e.pausedUntil > now) {
  return [{ json: { continuar: false, motivo: 'pausado_por_persona' } }];
}

const text = String(row.buffer ?? '').trim() || base.text;
return [{ json: { continuar: true, phone: base.phone, name: base.name, kind: base.kind, messageId: base.messageId, text, e } }];

// Arma el mensaje que recibe el modelo: texto del cliente + lo que ya sabemos + bloques autorizados.
const cfg = $('Config').first().json;
const ficha = $('Ficha de servicios').first().json;
const u = $('¿Último mensaje?').first().json;
const e = u.e ?? {};

const now = $now.setZone('America/Asuncion');
const hhmm = now.toFormat('HH:mm');
const dias = String(cfg.atencionDias ?? '1,2,3,4,5').split(',').map((d) => Number(d.trim()));
const enHorario = dias.includes(now.weekday) && hhmm >= cfg.atencionDesde && hhmm < cfg.atencionHasta;

const sent = Object.entries(e.bloques ?? {})
  .filter(([, t]) => Date.now() - t < 6 * 3600e3)
  .map(([k]) => k);

const lines = [
  '=== MENSAJE DEL CLIENTE ===',
  u.text,
  '',
  '=== AHORA ===',
  `${now.setLocale('es').toFormat("cccc dd/MM/yyyy HH:mm")} (hora de Paraguay)`,
  `El equipo humano está ${enHorario ? 'DENTRO' : 'FUERA'} del horario de atención (${cfg.atencionDesde} a ${cfg.atencionHasta}).`,
  '',
  '=== DATOS YA CONOCIDOS DE ESTA PERSONA ===',
  `Nombre en WhatsApp: ${u.name || 'no informado'}`,
  `Etapa actual: ${e.stage || 'NUEVO'}`,
  `Mensajes del cliente hasta ahora: ${e.inCount || 1}`,
  `Datos del interesado: ${JSON.stringify(e.lead ?? {})}`,
  e.ubicacion ? 'Ya compartió su ubicación GPS.' : '',
  (e.adjuntos ?? []).length ? `Ya envió ${(e.adjuntos ?? []).length} adjunto(s) (imágenes/documentos).` : '',
  '',
  '=== BLOQUES YA ENVIADOS EN LAS ÚLTIMAS 6 HORAS (no los repitas salvo que los pida de nuevo) ===',
  sent.length ? sent.join(', ') : 'ninguno',
  '',
  '=== BLOQUES AUTORIZADOS (código: contenido) ===',
  ...Object.entries(ficha.catalogo).map(([k, v]) => `${k}: ${v}`),
  '',
  '=== TEMAS SIN TARIFA CARGADA (derivar a una persona, no inventar) ===',
  ...ficha.sinTarifa.map((t) => `- ${t}`),
];

return [{ json: { phone: u.phone, name: u.name, aiInput: lines.filter((l) => l !== undefined).join('\n'), enHorario } }];

// Valida la salida del modelo, arma los mensajes a enviar y actualiza la ficha del chat.
const cfg = $('Config').first().json;
const ficha = $('Ficha de servicios').first().json;
const ctx = $('Armar contexto IA').first().json;
const last = $('¿Último mensaje?').first().json;
const e = last.e ?? {};
const ai = $input.first().json ?? {};
const now = Date.now();

const STAGES = ['NUEVO', 'CALIFICANDO', 'COSTOS_ENVIADOS', 'DOCUMENTACION', 'LISTO_PARA_INICIAR', 'DERIVADO', 'DESCARTADO'];
const clean = (v) => String(v ?? '').replace(/\r/g, '').trim();
const SIN_IA = 'Disculpe, en este momento no puedo darle la información. Le paso con el Lic. José Rojas, que le responde a la brevedad 🙏';

// 1) Parseo tolerante (el modelo puede envolver el JSON en ```).
const rawOut = clean(ai.output ?? ai.text ?? '');
let p = null;
try {
  const i = rawOut.indexOf('{');
  const j = rawOut.lastIndexOf('}');
  p = JSON.parse(rawOut.slice(i, j + 1));
} catch { p = null; }
const fallback = p === null;
if (fallback) p = { needs_human: true, human_reason: 'FALLA_IA', reply_parts: [SIN_IA], blocks: [], stage: 'DERIVADO' };

// 2) Red de seguridad: un precio escrito "a mano" por el modelo se descarta (solo valen los bloques).
const tienePrecio = (t) => /\bGs\.?\s*\d|\d{1,3}(?:\.\d{3})+/.test(t);
const descartados = [];
const parts = (Array.isArray(p.reply_parts) ? p.reply_parts : [])
  .map(clean).filter(Boolean)
  .filter((t) => { if (tienePrecio(t)) { descartados.push(t); return false; } return true; })
  .slice(0, 2);
let closing = clean(p.closing);
if (tienePrecio(closing)) { descartados.push(closing); closing = ''; }

// 3) Bloques: solo códigos conocidos y no repetidos en 6 h.
const bloquesPrevios = e.bloques ?? {};
const bloques = [...new Set(Array.isArray(p.blocks) ? p.blocks : [])]
  .filter((k) => ficha.bloques[k] && !(bloquesPrevios[k] && now - bloquesPrevios[k] < 6 * 3600e3))
  .slice(0, 5);

let needsHuman = p.needs_human === true;
let reason = clean(p.human_reason) || null;
// Si descartamos un precio y no queda nada útil, mejor una persona.
if (!parts.length && !bloques.length && !closing) {
  needsHuman = true; reason = reason || 'SIN_RESPUESTA_UTIL';
  parts.push(descartados.length ? 'Permítame un momento, le paso con el Lic. José Rojas para confirmarle ese dato 🙏' : SIN_IA);
}

const textos = [...parts, ...bloques.map((k) => ficha.bloques[k]), ...(closing ? [closing] : [])];
const to = '+' + ctx.phone;
const mensajes = textos.map((text) => ({ to, text }));

// 4) Ficha del chat.
for (const [k, v] of Object.entries(p.lead ?? {})) {
  if (v !== null && v !== undefined && clean(v) !== '') e.lead = { ...(e.lead ?? {}), [k]: v };
}
if (!e.name && e.lead?.nombre) e.name = e.lead.nombre;
e.intent = clean(p.intent) || e.intent || null;
e.stage = needsHuman ? 'DERIVADO' : (STAGES.includes(p.stage) ? p.stage : (e.stage || 'CALIFICANDO'));
if (bloques.includes('EAS_COSTO')) e.priced = true;
e.bloques = { ...bloquesPrevios };
for (const k of bloques) e.bloques[k] = now;
e.hist = [...(e.hist ?? []), now];
e.botReplies = (e.botReplies || 0) + 1;
e.lastBotAt = now;
e.lastOutAt = now;
e.followUpSent = false;
if (needsHuman) {
  const horas = Number(cfg.pausaHoras) > 0 ? Number(cfg.pausaHoras) : 8;
  e.pausedUntil = now + horas * 3600e3;
  e.derivadoMotivo = reason;
}

// 5) Aviso interno y sincronización opcional con el CRM.
const lead = e.lead ?? {};
const aviso = needsHuman
  ? [
      '🔔 Lead para atender',
      `Nombre: ${lead.nombre || e.name || ctx.name || 'sin dato'}`,
      `Teléfono: +${ctx.phone}`,
      `Interés: ${lead.tipo || e.intent || 'sin dato'}${lead.rubro ? ' · rubro: ' + lead.rubro : ''}`,
      `Motivo: ${reason || 'sin dato'}`,
      `Etapa: ${e.stage}`,
      `Último mensaje: "${clean(last.text).slice(0, 300)}"`,
      ctx.enHorario ? '' : '(Entró fuera de horario de atención)',
    ].filter(Boolean).join('\n')
  : '';

const crmSync = cfg.crmActivo === true && Boolean(lead.nombre || e.name);
const crm = crmSync ? {
  firstName: String(lead.nombre || e.name).slice(0, 80),
  phone: '+' + ctx.phone,
  source: 'WHATSAPP_COMERCIAL',
  tags: ['asistente-whatsapp', lead.tipo ? String(lead.tipo).toLowerCase() : 'consulta'],
  customData: { rubro: lead.rubro ?? null, ciudad: lead.ciudad ?? null, etapa: e.stage, tieneRuc: lead.tiene_ruc ?? null },
  upsert: true,
} : null;

return [{
  json: {
    phone: ctx.phone,
    mensajes,
    estado: JSON.stringify(e),
    handoff: needsHuman,
    aviso,
    avisoTo: cfg.notificarA ? '+' + String(cfg.notificarA).replace(/\D/g, '') : '',
    crmSync,
    crm,
    meta: { fallback, descartados, bloques, stage: e.stage },
  },
}];

// Cada hora: ofrece UN recordatorio a quien recibió el presupuesto y no volvió a escribir.
const cfg = $('Config').first().json;
if (cfg.seguimientoActivo !== true || cfg.botActivo === false) return [];

const ahora = $now.setZone('America/Asuncion');
const hhmm = ahora.toFormat('HH:mm');
const dias = String(cfg.atencionDias ?? '1,2,3,4,5').split(',').map((d) => Number(d.trim()));
if (!dias.includes(ahora.weekday) || hhmm < cfg.seguimientoDesde || hhmm > cfg.seguimientoHasta) return [];

const last9 = (v) => String(v ?? '').replace(/\D/g, '').slice(-9);
const lista = (v) => String(v ?? '').split(/[,;\s]+/).map(last9).filter(Boolean);
const prueba = lista(cfg.soloPrueba);
const excluidos = lista(cfg.excluir);

const now = Date.now();
const minimo = (Number(cfg.seguimientoHoras) || 22) * 3600e3;
const out = [];

for (const { json: row } of $input.all()) {
  if (!row?.estado) continue;
  let e;
  try { e = JSON.parse(row.estado); } catch { continue; }
  if (!e.phone || e.stage !== 'COSTOS_ENVIADOS' || e.followUpSent) continue;
  if (e.pausedUntil && e.pausedUntil > now) continue;
  if (!e.lastOutAt || !e.lastInAt || e.lastInAt > e.lastOutAt) continue; // el cliente habló último: no corresponde
  const silencio = now - e.lastOutAt;
  if (silencio < minimo || silencio > 72 * 3600e3) continue;
  if (excluidos.includes(last9(e.phone))) continue;
  if (prueba.length && !prueba.includes(last9(e.phone))) continue;

  const nombre = (e.lead?.nombre || e.name || '').split(' ')[0];
  const text = `Buenas${nombre ? ' ' + nombre : ''}, le escribe nuevamente el equipo de la Consultora ROMEZ. ¿Pudo revisar la información que le enviamos? Si le quedó alguna duda, avíseme y con gusto se la resuelvo 🙌`;

  e.followUpSent = true;
  e.lastOutAt = now;
  e.lastBotAt = now;
  out.push({ json: { phone: e.phone, to: '+' + e.phone, text, estado: JSON.stringify(e) } });
}
return out;
